    'connect' | 'startTransaction' | 'commitTransaction' | 'rollbackTransaction' | 'release',
    jest.Mock
  >;

  const expectNothingInserted = (): void => {
    expect(manager.save).not.toHaveBeenCalled();
    expect(manager.insert).not.toHaveBeenCalled();
