        { provide: DataSource, useValue: { createQueryRunner: () => ({ ...queryRunner, manager }) } },
      ],
    }).compile();
    repository = moduleRef.get(IdempotentBookingRepository);
  });

  describe('findByKey', () => {
    it.each([['the stored row', storedRow(FINGERPRINT)], ['null for an unused key', null]])(
      'returns %s',
