  const sentStartsAt = toInstantOrNull(changes.startsAt);
  const sentEndsAt = toInstantOrNull(changes.endsAt);
  const startsAt = sentStartsAt ?? stored.startsAt;
  const endsAt = sentEndsAt ?? stored.endsAt;
