#!/usr/bin/env bash
# Shared helpers for the quickstart scenarios. Usage: source lib.sh <gateway-port>
API="http://localhost:${1:?gateway port}/api"
FAILS=0

room() { curl -s "$API/rooms?limit=12" | jq -r ".items[$1].id"; }

# book <roomId> <start> <end> [key] -> "<status> <errorCode|id>"
book() {
  jq -n --arg r "$1" --arg s "$2" --arg e "$3" \
    '{roomId:$r,title:"Overlap check",organizerEmail:"qa.user+overlap@example.com",startsAt:$s,endsAt:$e}' |
  curl -s -w '\n%{http_code}' -X POST "$API/bookings" -H 'Content-Type: application/json' \
    -H "Idempotency-Key: ${4:-$(uuidgen)}" -d @- |
  jq -rs '"\(.[1]) \(.[0].errorCode // .[0].id)"'
}

status_of() { echo "${1%% *}"; }
detail_of() { echo "${1#* }"; }

# patch <id> <json> -> "<status> <errorCode|->"
patch() {
